import 'package:flutter/material.dart';
import '../../../models/regular_customer.dart';
import '../../../services/customer_service.dart';

class AddCustomerScreen extends StatefulWidget { final RegularCustomer? customer; const AddCustomerScreen({super.key, this.customer}); @override State<AddCustomerScreen> createState() => _AddCustomerScreenState(); }
class _AddCustomerScreenState extends State<AddCustomerScreen> {
  final _form = GlobalKey<FormState>(); late final TextEditingController _name, _phone, _notes; bool _saving = false;
  @override void initState() { super.initState(); final c = widget.customer; _name = TextEditingController(text: c?.name ?? ''); _phone = TextEditingController(text: c?.phone ?? ''); _notes = TextEditingController(text: c?.notes ?? ''); }
  @override void dispose() { _name.dispose(); _phone.dispose(); _notes.dispose(); super.dispose(); }
  Future<void> _save() async { if (!_form.currentState!.validate()) return; setState(() => _saving = true); try { final now = DateTime.now(); final old = widget.customer; final customer = old == null ? RegularCustomer(id: now.microsecondsSinceEpoch.toString(), name: _name.text.trim(), phone: _phone.text.trim(), notes: _notes.text.trim(), createdAt: now, updatedAt: now) : old.copyWith(name: _name.text.trim(), phone: _phone.text.trim(), notes: _notes.text.trim(), updatedAt: now); if (old == null) { await CustomerService.instance.addCustomer(customer); } else { await CustomerService.instance.updateCustomer(customer); } if (mounted) Navigator.pop(context); } catch (e) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Could not save customer: $e'))); } finally { if (mounted) setState(() => _saving = false); } }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: Text(widget.customer == null ? 'Add regular customer' : 'Edit customer')), body: Form(key: _form, child: ListView(padding: const EdgeInsets.all(16), children: [TextFormField(controller: _name, textCapitalization: TextCapitalization.words, decoration: const InputDecoration(labelText: 'Customer name', border: OutlineInputBorder()), validator: (v) => v == null || v.trim().isEmpty ? 'Enter a name' : null), const SizedBox(height: 12), TextFormField(controller: _phone, keyboardType: TextInputType.phone, decoration: const InputDecoration(labelText: 'Phone (optional)', border: OutlineInputBorder())), const SizedBox(height: 12), TextFormField(controller: _notes, minLines: 3, maxLines: 5, decoration: const InputDecoration(labelText: 'Notes (optional)', border: OutlineInputBorder())), const SizedBox(height: 20), FilledButton.icon(onPressed: _saving ? null : _save, icon: const Icon(Icons.save), label: Text(_saving ? 'Saving...' : 'Save customer'))])));
}
